using System;using System.IO;using System.Linq;using System.Collections.Generic;using V15Voice;
public static class CommunityVoiceTests {
 static int n;static void Check(bool b,string title){if(!b)throw new Exception(title);Console.WriteLine("PASS "+title);n++;}static void Reject(Action action,string contains,string title){try{action();}catch(Exception e){Check(e.Message.Contains(contains),title+" · "+e.Message);return;}throw new Exception(title);}
 public static void Main(){
  string d=Path.Combine(Path.GetTempPath(),"V15 cộng đồng "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);var c=new VoiceCatalog(Path.Combine(d,"absent.tsv"),Path.Combine(d,"notes.tsv"));CommunityVoices.Add(c);var p=c.Get("C:adam_rvc");
  Check((int)EngineKind.VieNeu==6&&(int)EngineKind.Rvc==7,"Existing engine numbers stay compatible; RVC appended");Check(c.Count==1&&!c.All.Any(x=>x.Key=="C:sarah_atlas"),"Only validated Adam is selectable; failed Sarah is excluded");Check(p.Kind==EngineKind.Rvc&&p.Name.Contains("cộng đồng"),"Adam has distinct source and engine identity");Check(!p.Recommended&&p.Grade=="Chưa chấm sao","No invented recommendation or community score");Check(p.Styles.Contains("Kể chuyện")&&p.Styles.Contains("Review"),"Style suggestions are available for filtering");Check(p.Source.Contains("huggingface.co")&&p.StyleReason.Contains("Chưa xác minh quyền"),"Model source and unverified commercial provenance remain visible");
  using(var e=new KokoroEngine{Root=d,Kind=EngineKind.Rvc,ModelFolder=CommunityVoices.AdamFolder,VoiceName=p.Name,Threads=3,DeviceMode="gpu"}){
   Check(e.ModelFile==CommunityVoices.RvcModel(d)&&e.VoiceFolder.EndsWith("weights"),"RVC resolves its own weights without overwriting existing models");using(var b=CommunityVoices.BaseEngine(e)){Check(b.Kind==EngineKind.Kokoro&&b.Speaker==16,"Base speech uses Michael rather than Kokoro Adam");Check(b.Threads==3&&b.DeviceMode=="gpu","Base speech respects existing device and thread settings");}
   Reject(()=>e.CheckFiles(),"Thiếu gói Adam RVC","Missing files give actionable message");e.ModelFolder="unknown";Reject(()=>e.CheckFiles(),"chưa được hỗ trợ","Unknown RVC folder rejected");e.ModelFolder=CommunityVoices.AdamFolder;e.Cancel();Reject(()=>e.Generate("Example.",1,Path.Combine(d,"out.wav")),"canceled","Cancel before generation prevents process start");Check(!Directory.GetFiles(d,"*.wav").Any(),"Cancelled generation leaves no output");
  }
  using(var r=new KokoroEngine{Root=d,Kind=EngineKind.Rvc,ModelFolder=CommunityVoices.AdamFolder,VoiceName=p.Name})using(var k=new KokoroEngine{Root=d,Kind=EngineKind.Kokoro,Speaker=11,VoiceName="Adam"}){
   string key=SpeechArchive.Key(r,"Same words.",1);Check(key!=SpeechArchive.Key(k,"Same words.",1),"RVC cache cannot collide with Kokoro Adam");string index=Path.Combine(CommunityVoices.RvcHome(d),"weights","adam.index");Directory.CreateDirectory(Path.GetDirectoryName(index));File.WriteAllText(index,"fixture index");Check(key!=SpeechArchive.Key(r,"Same words.",1),"Index changes invalidate RVC cached audio");key=SpeechArchive.Key(r,"Same words.",1);string baseFile=Path.Combine(d,"model","voices.bin");Directory.CreateDirectory(Path.GetDirectoryName(baseFile));File.WriteAllText(baseFile,"fixture");Check(key!=SpeechArchive.Key(r,"Same words.",1),"Changes to base voice bank invalidate RVC cached audio");
   var cues=Scripts.ParseSrt("1\n00:00:00,000 --> 00:00:04,000\nThese words remain untouched.\n");string input=Path.Combine(d,"source.srt");File.WriteAllText(input,Scripts.ToSrt(cues));string hash=StateFiles.Hash(input);var options=new RenderOptions{Breathing=BreathMode.None,ReportContext=new VoiceReportContext{SourcePath=input,Purpose="RVC missing-file test"}};Reject(()=>Renderer.Render(cues,r,options,OutputFiles.Beside(input),(i,m)=>{}),"Thiếu gói Adam RVC","Render does not silently substitute another voice when RVC is incomplete");Check(options.RunReport!=null&&File.Exists(options.RunReport.PathName),"Failed RVC render still writes report");Check(StateFiles.Hash(input)==hash&&!File.Exists(OutputFiles.Beside(input)),"Failed RVC leaves SRT and any expected WAV untouched");
  }
  var settings=new VoiceSettings{Key="C:adam_rvc",Device="auto"};Check(VoiceSettings.From(settings.Xml()).Key==settings.Key,"Presets/session can restore community voice key");Console.WriteLine("TOTAL COMMUNITY "+n+" passed.");
 }
}
